INSERT INTO composition_translations(composition_id,locale,title,alternate_titles,summary,description,status) VALUES
('a32a3e07-f63e-4e3d-8b91-95c2e56333d6','zh-CN','《美德剧》','{}','希尔德加德·冯·宾根的sacred drama代表作，创作于1151年。','《美德剧》在本图集中连接希尔德加德·冯·宾根、利摩日、liturgical drama、相关乐器与历史事件。详情文字为原创策展摘要。','published'),
('a32a3e07-f63e-4e3d-8b91-95c2e56333d6','en','Ordo Virtutum','{}','A representative sacred drama by Hildegard of Bingen, composed in 1151.','Ordo Virtutum connects Hildegard of Bingen, Limoges, its liturgical drama, instruments, and historical events. The description is original editorial prose.','published'),
('e5b4a449-eb9d-4b23-8e3c-93aac312e986','zh-CN','《啊，最翠绿的枝条》','{}','希尔德加德·冯·宾根的sacred song代表作，创作于1150年。','《啊，最翠绿的枝条》在本图集中连接希尔德加德·冯·宾根、利摩日、sequence、相关乐器与历史事件。详情文字为原创策展摘要。','published'),
('e5b4a449-eb9d-4b23-8e3c-93aac312e986','en','O viridissima virga','{}','A representative sacred song by Hildegard of Bingen, composed in 1150.','O viridissima virga connects Hildegard of Bingen, Limoges, its sequence, instruments, and historical events. The description is original editorial prose.','published'),
('97f0942a-e051-4ee3-b411-af9c53034ab0','zh-CN','《众目皆见》','{}','莱奥南的organum代表作，创作于1198年。','《众目皆见》在本图集中连接莱奥南、巴黎、two-part organum、相关乐器与历史事件。详情文字为原创策展摘要。','published'),
('97f0942a-e051-4ee3-b411-af9c53034ab0','en','Viderunt omnes','{}','A representative organum by Léonin, composed in 1198.','Viderunt omnes connects Léonin, Paris, its two-part organum, instruments, and historical events. The description is original editorial prose.','published'),
('d8444d6c-347b-49d4-83b0-34cb71999b1d','zh-CN','《众目皆见》','{}','佩罗坦的organum代表作，创作于1198年。','《众目皆见》在本图集中连接佩罗坦、巴黎、four-part organum、相关乐器与历史事件。详情文字为原创策展摘要。','published'),
('d8444d6c-347b-49d4-83b0-34cb71999b1d','en','Viderunt omnes','{}','A representative organum by Pérotin, composed in 1198.','Viderunt omnes connects Pérotin, Paris, its four-part organum, instruments, and historical events. The description is original editorial prose.','published'),
('d0ad2e6a-844c-4480-b375-b7f23568d8cd','zh-CN','《圣母弥撒》','{}','纪尧姆·德·马肖的mass代表作，创作于1360年。','《圣母弥撒》在本图集中连接纪尧姆·德·马肖、兰斯、cyclic mass、相关乐器与历史事件。详情文字为原创策展摘要。','published'),
('d0ad2e6a-844c-4480-b375-b7f23568d8cd','en','Messe de Nostre Dame','{}','A representative mass by Guillaume de Machaut, composed in 1360.','Messe de Nostre Dame connects Guillaume de Machaut, Reims, its cyclic mass, instruments, and historical events. The description is original editorial prose.','published'),
